) AS (
  VALUES 
    (110::BIGINT, 'Hace lo posible por no ir a clases o hacerla virtual. Se desvía del tema casi siempre. Habla hasta por los codos. Es aburridillo como cualquier ciencia social de este tipo. Deja trabajillos normales de investigar cosillas pero la verdad es bien fácil (ni sé como me saqué 95 en su clase)'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases largas']::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, '4f43d68aa0c6ef1b4dc1118df9264577e070dc1c568c07908251fdcad870ff84'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'Pasa cancelando clases, deja muchas lecturas para hacer trabajos, pero por el tema de cancelación de clases al final de semestre termina pidiendo varias cosas sencillas, usted nada más entregue todo y pasa con teja'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas']::TEXT[], '2025-12-24T00:00:00+00:00'::TIMESTAMPTZ, 'a7a3cffb30ee2bdb395c92033ffd76c1b2194fd4a8412ce564dd92aed90d5ff9'::TEXT, ARRAY[1004]::BIGINT[]),
    (110::BIGINT, 'Si el profesor es bien comunista, en algunas ocasiones de la clase se desvía del tema de estudio y habla de como el imperialismo de USA es una m*3rd4 etc. Deja lecturas que sabe que no leeremos y en ocasiones tiene un lenguaje soez, se pasa fácil siempre que cumpla con tareas y exámenes.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas']::TEXT[], '2025-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'e3df9cb5282719aba230e6ef57fb6c6a709f373b352c4d7ac1f26564d33a9843'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'El profesor es excesivamente zurdo y tiene cero respeto por otras ideologías. El curso en realidad es sencillo pero es insoportable escucharlo hablar'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-09-12T00:00:00+00:00'::TIMESTAMPTZ, 'a51e1606761b46e3be0537cca3349da485c2b626b990932485acace69d00ac3e'::TEXT, ARRAY[1004]::BIGINT[]),
    (110::BIGINT, 'Es un profe muy relajado, es consciente que su clase es de un crédito nada más. Se pasa super fácil y los exámenes son trabajos para la casa. A veces no se le entiende lo que dice porque habla muy rápido. Cancela las clases a ultima hora y muchas veces en el semestre. Las clases son algo aburridas'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'c36554d21550d194d870d648fbc8054b7f0b74bb54fb633d800b0c87d5c288f9'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'Bastante chill la clase'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-12T00:00:00+00:00'::TIMESTAMPTZ, 'b7c31dc2dd56a6f5e17b1fe4fb55efb90d8252a1c614dc8dbe42e9b6c6fa15a9'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'El profe es muy tranquilo, tipo sabe que el curso no es tan interesante para nuestras carreras, así que busca hablar a través de ejemplos y es muy gracioso. Califica super suave, lo único malo es que las clases no son tan interesantes, pero con él se pasa fácil y aprendes una que otra cosa.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2024-11-07T00:00:00+00:00'::TIMESTAMPTZ, '912eb674e62509a5416e1e94c3c2847da415326d5118e640f08e76ff428472fa'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'Recomendado, sabe que el curso vale 1 crédito entonces califica súper suave, no pasa lista y hace las clases interesantes y no muy largas, a veces se va por las ramas del tema pero igual es un punto de vista interesante, además es todo un personaje.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2023-12-07T00:00:00+00:00'::TIMESTAMPTZ, '5212eba196677c171276931e5096edd9e051c0040682e3e9fd51e4f41ff08bea'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'El curso es muy aburrido pero él lo hace divertido, califica extremadamente fácil. Deja como 5 ensayos en todo el curso y 2 exámenes. A veces cancela clases o las hace asincrónicas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2023-12-01T00:00:00+00:00'::TIMESTAMPTZ, '7cb013761b273ad523d0d0661410fe1f7889b4dc1a4f8c3814248cc7e9c22651'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'Este semestre casi no dio clases por asuntos de salud, pero nunca pasa asistencia y todo el curso son 5 trabajos facilísimos. En un real que sabe que este curso no es importante y casi que lo regala; todos nos fuimos con 100. Lleve todo lo que pueda con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases largas', 'Clases excelentes']::TEXT[], '2023-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'b64236f3c112845d7edc1db773378aeb78ce1835e3b4e3063d3996f9c4c1376a'::TEXT, ARRAY[1004]::BIGINT[]),
    (110::BIGINT, 'Exelente profesor. Califica sumamente suave. Explica temas aburridos de maneras interesantes. A veces se desvía del tema, pero esto hace que se vea otra visión de los mismos. Totalmente recomendado si quiere llevar el curso relajado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '8f0a0d085f0769c13d4a5747053acfc37eda4b5ffeba67d6380bbebfca25f6d0'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'No es mal profe solo que las clases en si se hacen largas y se desvía bastante del tema, en general el curso se pasa relax y no califica duro los trabajos.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'd483ecfd664bce426d3b8bc75e34debd42149328ee43c213bef7fbe913c784bc'::TEXT, ARRAY[1004]::BIGINT[]),
    (110::BIGINT, 'Me costaba mucho seguirle el hilo al profe durante sus clases, se desviaba bastante del tema. Además, en ocasiones usaba un vocabulario un poco complejo. Nunca buscaba la participación de los estudiantes, por lo que parecía que uno llegaba a escuchar una grabación, en algunas clases casi me duermo.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-30T00:00:00+00:00'::TIMESTAMPTZ, '55667834714ab5f41ee80df1e9008ae62348f16c2404e13323c209851a448a14'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'Se pasa regalado, muy tuanis, chill. Extremadamente zurdo, las clases llegan a ser incluso adoctrinantes pero no les afecta en trabajos si exponen ptos de vista distintos. Habla demasiado, se desvía un montón pero es graciosillo y se nota la "Pasión/conocimiento".'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2022-11-20T00:00:00+00:00'::TIMESTAMPTZ, '801c7319eda2a6aa274eb25342de41cb6681d9b575f80a495c8f4732f92eaf99'::TEXT, ARRAY[1004]::BIGINT[]),
    (110::BIGINT, 'En general es un buen profe. Se pasa el curso relajado, revisa todo muy suave. Durante las clases se abarcan muchos temas profundamente, y por eso el curso es interesante. Eso sí, tiende a hablar demasiado y se desvía mucho de cada tema, lo cual puede ser molesto o vacilón según su punto de vista.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, '146f9c6cd52ce919c83b5fadc2f39622604488e17df2e05854d44b605b620050'::TEXT, ARRAY[1004]::BIGINT[]),
    (110::BIGINT, 'El profe es god, para ser una clase aburrida por el tipo de materia que es, el mae lo hace bastante interesante y vacilón.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, '2d7d40e9187c8ff3a197880b976ff3148949f15ec7a62f96c8039dbf6c86ac83'::TEXT, ARRAY[1004]::BIGINT[]),
    (110::BIGINT, 'Pide varios trabajos escritos (largos) en el semestre pero nada imposible. Es muy gracioso y hace las clases entretenidas. Califica súper bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, '1088f9efc80b50f506c12a45620a2c42dcc3383f6d307f00182c2e30c9285887'::TEXT, ARRAY[1004]::BIGINT[]),
    (110::BIGINT, 'Demasiado buen profe, las clases son asincronicas por lo que hay que ser autodidacta e ir al día con ellas. Pero lo trabajos son regalados si ve las clases.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2021-12-14T00:00:00+00:00'::TIMESTAMPTZ, 'c576d8ce0380ffb5b1a5d78dbb20bd40b26bdf76a6579ac01273f70e703fe570'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'Casi todas las clases son asincrónicas y las que no duran como 15 minutos. Realmente el curso se pasa bastante fácil, con los audios y las presentaciones basta y no califica duro. A veces se desvía del tema y usa muletillas, pero hizo ese curso de m*erda menos aburrido de lo que puede llegar a ser.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo']::TEXT[], '2021-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'efc43fa333e0b2ea32749f21ac07c5224a774a6f425f4196168991f8de8660a2'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'El curso lo hace muy fácil. Solo 4 evaluaciones en todo el semestre y no califica duro. Clases asincrónicas tipo podcast. Si de verdad quiere escucharlas hágalo, son muy graciosas, pero en realidad no es necesario.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '3f29a9ecbd7000f37eb422289e2f0cdfcacf30ed553e84faae13974ac0266692'::TEXT, ARRAY[1004]::BIGINT[]),
    (110::BIGINT, '(Virtual) Él es muy confianzudo, las clases las da completamente asincrónicas y sólo hace unas cuantas reuniones cada cierto tiempo para explicar tareas o examen (análisis de caso y comprobación de lectura respect.) No aclara casi nada y todo lo maneja a puras grabaciones de audio y Power Point.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2021-07-18T00:00:00+00:00'::TIMESTAMPTZ, 'dea2194bbbac555048a24e1f8a407fca05d114fdf54fab673e159c35614272c6'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'El curso de intro tec. ciencia y tecnología en general es bastante aburrido y se nota la parcialidad política de este profesor, sin embargo es bastante relajado y pura vida. Sus trabajos son básicamente echarse la hablada en ensayos y se pasa facilito. Recomendado (menos si es conservador envenenado'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Pocos exámenes']::TEXT[], '2021-06-25T00:00:00+00:00'::TIMESTAMPTZ, '1ed97fc4a6ab1bc28023b736b332657088d7c01ba04f5f89841edde9526ba7ff'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'Sí, tiene muchas muletillas y a veces se desvía del tema, pero en general es claro. Los trabajos son sencillos, es flexible con la entrega, los exámenes se pueden hacer en pareja y califica suave.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'f53abd0ab35592b3103bb032a4e22bb2c6721447e9e8ca8b40fc55fa0334a3e5'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, '507c6318895c28d83dbc25e8c2cf6f9150de66101b93182218f7e031ad98a687'::TEXT, ARRAY[1004]::BIGINT[]),
    (110::BIGINT, 'Que hijueputa curso mas aburrido... bueno siguiendo, este profe se lo toma muy en serio, los exámenes son una parida, las clases lo más aburrida qué hay. PERO de más 16 clases que tuvimos que recibir el cancelo como 7, entonces si metan el curso para salir temprano!'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2019-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'f09096ad72e28f1cef75cbc6983abd6b87d531ffec539f69b71d25c415a49f72'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'Es super flexible con la asistencia, casi nunca pasa lista, califica suave, no deja lecturas, se la pasa hablando todas las clases tiene muchas muletillas y puede resultar molesto, siempre se sale temprano de las clases el curso se pasa practicamente solo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2019-06-13T00:00:00+00:00'::TIMESTAMPTZ, '4d069b83f8a7d976aa81a7ffe15c98591e2de78eb7be276297aa8385c5114bb7'::TEXT, ARRAY[1004]::BIGINT[]),
    (110::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'd9d69114f6d7c150c859e9f8734839ebb345f3507757ab916f4bdad4e1b953a1'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'Hace la materia interesante, ya que toma aspectos de la actualidad, es cómico con sus explicaciones. Si califica un poco duro los trabajos.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, '81a8179a5c586f0bf0a66cb4ec5808d712e26233aebe23756a46f5621754cca7'::TEXT, ARRAY[1004]::BIGINT[]),
    (110::BIGINT, 'Es un curso muy fácil, no deja demasiados trabajos, y si deja en realidad no quitan demasiado tiempo. Excelente profesor!! (Nunca pasa lista)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-14T00:00:00+00:00'::TIMESTAMPTZ, '3a92f21a9b3deab1be781285502715c165849b0e78584e8a0e223c7522d3905d'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'Curso REGALADO, aunque deja trabajos medio larguillos, si lee las presentaciones que él hace ud defijo pasa!!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-10-29T00:00:00+00:00'::TIMESTAMPTZ, 'a878cc42c1a176f18d833abfb0b797cfb4160617279f9ae5a192972ffd87af25'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'Es un profe relajado, deja trabajos pero lo normal, son fáciles de hacer'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2018-08-12T00:00:00+00:00'::TIMESTAMPTZ, '1a403782967ac39c275fa7e61263696c8fbb8d47ae971c698f94051319b1e900'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'No es un mal profe, es solo que la materia del curso vuelve las clases demasiado aburridas, pero no es nada estricto, es bueno, comprensivo y motivado. Califica bastante suave y el curso con él es mucho más fácil comparado con otros profes. Además sube presentaciones y algunos libros que ayudan'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'dc750d9b4f5703ffc5f0f8794c2ec8c36461b91b3045793f7ce8450e582e785e'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'Excelente profesor!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '48ca50d1d574041d0339b38a616703eb249496c6cbe89fb5dae601093122d23e'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'No es estricto con las entregas ni la asistencia a clase, sin embargo si se molesta muy fácil cuando la gente habla entre ellos aunque sea sobre la materia, si están con el celular o computadora o si se retiran antes de la clases, sin embargo trata de terminarla antes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'eb3e9fb91c4fd5aba497fdfd3dcd2ab6df38960d8c564a3fc9b55cd46e808ca8'::TEXT, ARRAY[1004]::BIGINT[]),
    (110::BIGINT, 'La clase es fácil pero hay que estudiar para los examenes ! Las comprobaciones de lectura son demasiado fáciles'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '9a5fdcafa3f7d1d37cc9c1c4e969184391661dd0942ba2896cde0695c36b4c96'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'Explica bien, hace la clase no tan aburrida, es flexible con los tiempos de entrega de trabajos,califica suave.De "Verdad" lo recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '2f3c568384868f972245aae845261462e3c1b912a23fb040b1d2d3c7de6ab0ac'::TEXT, ARRAY[1004]::BIGINT[]),
    (110::BIGINT, 'Trata de hacer entretenida una clase aburrida y eso cuesta mucho, lo recomiendo porque sabe de lo que explica y lo realiza con esmero.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'f562a1676c0a55f7ac90d8debc30a27ce370bd4511d64f7256f428a20d76d694'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'El curso es aburrido pero el profe trata de hacerlo pasable. Las clases son cortas. La mayoría de trabajos los deja para la casa y en parejas. Sube las presentaciones al TECdigital y es lo único que se necesita. Se pasa fácil. El profe es bastante compresivo si uno entrega tarde un trabajo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-19T00:00:00+00:00'::TIMESTAMPTZ, '47a50385d2c5149b60512b15233fcd7662fc63f7c210be41e743ab22bb40ad67'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'El profesor intenta hacer sus clases lo más entretenidas posibles (aunque igual terminan siendo aburridas). Deja unos cuantos trabajos no muy complicados. Para los exámenes basta con estudiar bien las diapositivas que utilizó en clase (las sube). Demasiado fácil pasar con él.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'c7f0403b3134b0e2ca4022b2b4e43f1126ed110080276b8cdb3d56cfcc4e1ef8'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'Verdad'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-01T00:00:00+00:00'::TIMESTAMPTZ, '2b3e1ea6befa4ca3f109f223d6116b479d458dfb0ffac5399bb9c71870940f2e'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'Es comunista pero explica bien'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2018-03-10T00:00:00+00:00'::TIMESTAMPTZ, '7ca353e0dc7e0f772d874983e63653c9c56b56e9489fe7f83af593f5ade8e3c0'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'El profe es muy buena gente y a pesar de ser intro del bostezo, él se empeña en que sea una clase divertida. Realmente se siente que es muy apasionado al tema y uno se motiva a la hora de leer. Son muchas lecturas, pero él hace como un resumen de cada lectura y lo explica en clase. Es buen profe.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Requiere mucha lectura']::TEXT[], '2017-09-24T00:00:00+00:00'::TIMESTAMPTZ, '7d4c0c9e2d2c6eec869aacb9887da721b937b1736712093a14e6855e30a14488'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'A pesar de que todos dicen que intro es un bostezo, me parece que David se empeña mucho explicando la materia de una manera bastante clara, además de que ayuda mucho en consulta o incluso si uno le escribe por correo. Es realmente gracioso y muy buen profe...'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-06-16T00:00:00+00:00'::TIMESTAMPTZ, '39bc83cc8fc51819c62e36008785d4cfe2a527ee0495e0c10da47d19c407ffcd'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-13T00:00:00+00:00'::TIMESTAMPTZ, '227a49612e80975fe29ca5f23c427f10f7c600cc98feeac175500b372823538b'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'buena nota y explica bien.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'dd7366e6dc3037597709551ee9a24dd9487710a55f73fcaf6954e98c75ba1034'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'Hace que "Intro al bostezo" sea una clase realmente interesante y divertida'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2017-05-07T00:00:00+00:00'::TIMESTAMPTZ, '09d4f4ac21813b8b871076944f885cca7bbe4c4eaf2b24b850f289416534f370'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'Explica muy bien en la clase, la cual no es aburrida y si matrícula en la noche se sale temprano. Comprende mucho a los estudiantes y es divertido.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-26T00:00:00+00:00'::TIMESTAMPTZ, '11651fc20de94427e6ce4b7343029c3c73a3b71b6f0f65eedf5a1016cee2f135'::TEXT, ARRAY[1004]::BIGINT[]),
    (110::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'e4bf1cc712c86f0e311ef7343fdf18a20904e3e5ceebf571138fd5feba56d6d9'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'Es super buena nota, cuando uno tiene dudas aclara muy bien y evalua facil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, '5a153b7b27e94c000e2ebf5878580f1aca70a8939c8c08087e2e0aca9573d04f'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-03-16T00:00:00+00:00'::TIMESTAMPTZ, '30f17962e3d75a95aff20336bf14bc95a70055b0593b54c583ed0a94e77d3f7c'::TEXT, ARRAY[1004]::BIGINT[]),
    (110::BIGINT, 'Un profe muy tuanis. Logra que las clases sean amenas con materia aburrida, o bueno, por lo menos lo intenta. Califica suave y es muy accesible para las consultas. Con el mae se pasa fácil, eso sí tampoco es que uno no va a hacer nada.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2016-02-01T00:00:00+00:00'::TIMESTAMPTZ, '987532fe831080cb68c606f98eea7fc1654e686799b113b76812229362c26983'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'hace que no sea pesado el curso y al final da un resumen de las lecturas.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'fabba3e70d7c033c654f1cf629b7662fdb4d9a2aaa2b7bed58fe96cdb70ab5b6'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'hace que el curso no quite tiempo, es facil, buena nota, en fin un curso suave con el y se aprende!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-10T00:00:00+00:00'::TIMESTAMPTZ, '97e92f63bb9d7fa278785ebc09048674e7f6293517dd8e8b6ce9b39a2c11849c'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'Un profe diferente, pero muy tuanis. Si hay que estudiar con el, tampoco es que lo pasa de gratis. Es relajado, y da herramientas para comprender mejor la materia. Hace reir. Recomendado!'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2015-07-25T00:00:00+00:00'::TIMESTAMPTZ, '437150b502e999ceec969a6fc6ab5bc4c3e26fb0ed1c37bf5db822241ab3e3c3'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'Es super relajado con el curso, no deja muchas cosas que hacer en realidad casi nada, los exámenes son faciles y hace que la clase sea super divertida pero si le gusta que le pongan atención, recomendado 100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-28T00:00:00+00:00'::TIMESTAMPTZ, '020bb6d9e6a23c5beb13ea4e677076d56d3fb611d0164efe28c98156187f7ae8'::TEXT, ARRAY[559]::BIGINT[]),
    (110::BIGINT, 'Excelente profe, entiende que el estudiante está llevando otros cursos y hace que el de él sea mas ligero y entretenido (aunque la materia sea un bostezo, él intenta hacer de la clase mas corta o menos aburrida).'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-09T00:00:00+00:00'::TIMESTAMPTZ, '6ce684d1f17a6fd946e2452aba1d29eeccde34acc1c3e4407fe2729ca4cb0602'::TEXT, ARRAY[1004]::BIGINT[]),
    (110::BIGINT, 'Buen profe... si quiere pasar sin mucho esfuerzo lo recomiendo, y es un loco para hablar'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-03T00:00:00+00:00'::TIMESTAMPTZ, '7eceacc54a1c8ad8019daae8d792145dd1d3c8b1b13bd9abb81b48d6ca142fab'::TEXT, ARRAY[1004]::BIGINT[]),
    (110::BIGINT, 'Muy buen profe para introducción.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'df7f3a9c5b7ba35a5d0b931fcb8d60dcf7e272a4d39e71abe0cb7d87083b32cd'::TEXT, ARRAY[559]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
